import { test } from 'node:test';
import assert from 'node:assert/strict';
import { procurarPosicao, procurarUltimaPosicao } from './solution.mjs';

test('acha a posição de um item do meio', () => {
  assert.equal(procurarPosicao(['a', 'b', 'c'], 'b'), 1);
});

test('indexOf acha a primeira; lastIndexOf acha a última', () => {
  assert.equal(procurarPosicao([1, 2, 1], 1), 0);
  assert.equal(procurarUltimaPosicao([1, 2, 1], 1), 2);
});

test('item ausente devolve -1', () => {
  assert.equal(procurarPosicao([1, 2], 3), -1);
  assert.equal(procurarUltimaPosicao([], 1), -1);
});

test('recusa valor que não é lista', () => {
  assert.throws(() => procurarPosicao('ab', 'a'));
});

solutionCode:
export function procurarPosicao(lista, item) {
  if (!Array.isArray(lista)) {
    throw new Error('lista precisa ser um array');
  }
  return lista.indexOf(item);
}

export function procurarUltimaPosicao(lista, item) {
  if (!Array.isArray(lista)) {
    throw new Error('lista precisa ser um array');
  }
  return lista.lastIndexOf(item);
}
